  INSERT INTO jd_card_task (card_id, seq, task_ar, is_generic) SELECT card_id, 3, 'ينظم فهرساً هجائياً بأسماء كافة العاملين التابعين له للوصول الى صفحاتهم وبطاقاتهم الذاتية.', 'N' FROM jd_card WHERE card_code = 'JD-22-014';
  INSERT INTO jd_card_task (card_id, seq, task_ar, is_generic) SELECT card_id, 4, 'يشرف على تنظيم سجلاً أصولياً بخدمات العاملين ويفرد صفحة لكل عامل يدون عليها كافة المعلومات والوقوعات بدءاً من قرار التعيين والمباشرة حتى تاريخ احالته على التقاعد بما فيها الاجازات والمكافآت والعقوبات بأرقامها وتواريخها مع صورة لقيد نفوسه العائلي أصولاً .', 'N' FROM jd_card WHERE card_code = 'JD-22-014';
  INSERT INTO jd_card_task (card_id, seq, task_ar, is_generic) SELECT card_id, 5, 'يقوم بتنظيم اضبارة لكل عامل تحوي اوراقه الثبوتية وجميع القرارات والكتب الصادرة المتضمنة وقوعاته بما فيها قرار التعيين والمباشرة قبل تسليمها الى المحفوظات .', 'N' FROM jd_card WHERE card_code = 'JD-22-014';
  INSERT INTO jd_card_task (card_id, seq, task_ar, is_generic) SELECT card_id, 6, 'يدقق وثائق قبول طلبات التعيين والاحالة الى القضاء للمعاملات المتعلقة بتصفية الحقوق وتحريك الدعاوى ضد المنقطعين بالتنسيق مع مكتب التقاعد ومديرية القضايا والشؤون القانونية .', 'N' FROM jd_card WHERE card_code = 'JD-22-014';
  INSERT INTO jd_card_task (card_id, seq, task_ar, is_generic) SELECT card_id, 7, 'يتابع تنفيذ القرارات والكتب الصادرة عنها بشأن العمال مع المديريات التي يعملون بها من حيث الدوام المباشر والانفكاك .', 'N' FROM jd_card WHERE card_code = 'JD-22-014';
