  INSERT INTO jd_card_task (card_id, seq, task_ar, is_generic) SELECT card_id, 11, 'يمتنع عن إعطاء أية وثيقة أو معلومات عن العاملين لديه ويحافظ على سريتها ويعتبر مسؤولاً عن تسريبها واتلافها او ضياعها الا بإذن رسمي من رئيسه المباشر .', 'N' FROM jd_card WHERE card_code = 'JD-22-014';
